const rows = $input.all().map(i => i.json);
if (rows.length === 0) return [];
const lines = rows.map(r => {
  if (r.type === 'cumple') return '🎂 ¡Hoy cumple años *' + r.fullName + '*! ¡Felicítalo! 🎉';
  return '🎊 *' + r.fullName + '* cumple ' + r.years + (r.years === 1 ? ' año' : ' años') + ' con nosotros. ¡Gracias por tu trabajo! 💪';
});
const text = '🎉 *Celebraciones de hoy* 🎉\n\n' + lines.join('\n\n');
return [{ json: { text } }];

// Una felicitación en privado a quien celebra hoy. Sin teléfono registrado no
// se manda nada: el mensaje del grupo ya lo nombra.
const nombreCorto = (n) => {
  const p = String(n || '').trim().split(/\s+/);
  const primero = (p[0] || '').toUpperCase() === 'JESUS' && (p[1] || '').toUpperCase() === 'ADRIAN' ? p[1] : (p[0] || '');
  return primero.charAt(0).toUpperCase() + primero.slice(1).toLowerCase();
};
return $input.all().map(i => i.json).filter(r => r.phone).map(r => {
  const nombre = nombreCorto(r.fullName);
  const text = r.type === 'cumple'
    ? '🎂 *¡Feliz cumpleaños, ' + nombre + '!* 🎉\n\nDe parte de todo el equipo de TH San Agustín te deseamos un día increíble. ¡Que te la pases súper bien! 🥳'
    : '🎊 *¡Feliz aniversario, ' + nombre + '!*\n\nHoy cumples ' + r.years + (r.years === 1 ? ' año' : ' años') + ' con nosotros. Gracias por tu trabajo y tu compromiso. 💪';
  return { json: { phone: r.phone, text } };
});
